import sys
import json
import os

todo_file = '/work/todo.json'

def load_todos():
    if os.path.exists(todo_file):
        with open(todo_file, 'r') as f:
            return json.load(f)
    return []

def save_todos(todos):
    with open(todo_file, 'w') as f:
        json.dump(todos, f, indent=2)

def add_task(task):
    todos = load_todos()
    todos.append({'task': task, 'done': False})
    save_todos(todos)
    print(f'Added task: {task}')

def list_tasks():
    todos = load_todos()
    if not todos:
        print('No tasks.')
        return
    for i, todo in enumerate(todos, start=1):
        status = 'done' if todo['done'] else 'not done'
        print(f'{i}. [{status}] {todo["task"]}')

def done_task(index):
    todos = load_todos()
    if 1 <= index <= len(todos):
        todos[index-1]['done'] = True
        save_todos(todos)
        print(f'Marked task {index} as done')
    else:
        print(f'Invalid task number: {index}')

def remove_task(index):
    todos = load_todos()
    if 1 <= index <= len(todos):
        task = todos.pop(index-1)
        save_todos(todos)
        print(f'Removed task {index}: {task["task"]}')
    else:
        print(f'Invalid task number: {index}')

def usage():
    print('Usage: todo.py add <task> | list | done <task_number> | remove <task_number>')

def main():
    if len(sys.argv) < 2:
        usage()
        return
    cmd = sys.argv[1]
    if cmd == 'add' and len(sys.argv) > 2:
        add_task(' '.join(sys.argv[2:]))
    elif cmd == 'list':
        list_tasks()
    elif cmd == 'done' and len(sys.argv) == 3:
        try:
            index = int(sys.argv[2])
            done_task(index)
        except:
            print('Invalid task number')
    elif cmd == 'remove' and len(sys.argv) == 3:
        try:
            index = int(sys.argv[2])
            remove_task(index)
        except:
            print('Invalid task number')
    else:
        usage()

if __name__ == '__main__':
    main()
